import { fetchEventSource } from '@microsoft/fetch-event-source'

import { isMockEnabled } from './mock'
import {
  ApiRequestError,
  apiErrorFromResponse,
  notifyUnauthorized,
  refreshSession,
  resolveBaseUrl,
} from './client'
import type { ChatEventName, ChatStreamHandlers, ChatStreamRequest } from '@/types'
import { storage } from '@/utils/storage'

export type { ChatStreamHandlers }

/**
 * SSE 事件白名单。新增 `ChatEventDataMap` 事件时必须同步加入，
 * 否则真实模式会在 onmessage 里被当作未知事件丢弃（mock 不经过这里）。
 */
export const CHAT_EVENT_NAMES = [
  'conversation.created',
  'run.started',
  'message.created',
  'message.started',
  'message.delta',
  'reasoning.delta',
  'reasoning.done',
  'skill.activated',
  'tool.start',
  'tool.result',
  'a2a.task',
  'a2a.artifact',
  'a2a.input_required',
  'a2a.auth_required',
  'approval.required',
  'run.interrupted',
  'run.resumed',
  'workflow.step',
  'memory.saved',
  'notice',
  'message.done',
  'error',
  'ping',
] as const satisfies readonly ChatEventName[]

const CHAT_EVENTS = new Set<ChatEventName>(CHAT_EVENT_NAMES)

export function isChatEvent(value: string): value is ChatEventName {
  return CHAT_EVENTS.has(value as ChatEventName)
}

export async function readErrorBody(response: Response): Promise<unknown> {
  try {
    return await response.json()
  } catch {
    try {
      return await response.text()
    } catch {
      return null
    }
  }
}

async function connectOnce(
  payload: ChatStreamRequest,
  handlers: ChatStreamHandlers,
): Promise<void> {
  await fetchEventSource(`${resolveBaseUrl()}/chat/stream`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Accept: 'text/event-stream',
      Authorization: `Bearer ${storage.getAccessToken() ?? ''}`,
    },
    body: JSON.stringify(payload),
    signal: handlers.signal,
    openWhenHidden: true,

    async onopen(response) {
      if (!response.ok) {
        // 409 run_in_progress / 403 capability_disabled 等错误体是 JSON 信封，
        // 必须在 onopen 里读出来，否则 fetch-event-source 只会抛 HTTP 状态。
        throw apiErrorFromResponse(response.status, await readErrorBody(response))
      }
      const contentType = response.headers.get('content-type') ?? ''
      if (!contentType.includes('text/event-stream')) {
        throw new ApiRequestError('SSE 响应不是 text/event-stream', {
          code: 'invalid_sse_response',
          status: response.status,
        })
      }
      handlers.onOpen?.(response.headers.get('X-Run-ID'))
    },

    onmessage(event) {
      if (!event.event || event.event === 'ping') return
      if (!isChatEvent(event.event)) {
        console.debug('[chat] 忽略未知事件', event.event)
        return
      }
      let data: unknown = {}
      if (event.data) {
        try {
          data = JSON.parse(event.data) as unknown
        } catch {
          console.warn('[chat] 无法解析 SSE 数据帧', event.data)
          return
        }
      }
      handlers.onEvent(event.event, data)
    },

    onerror(error) {
      if (error instanceof ApiRequestError) {
        // 交给外层统一处理（409 恢复、401 刷新），不要再回调 onError。
        throw error
      }
      handlers.onError(error instanceof Error ? error : new Error(String(error)))
      throw error
    },

import { apiClient } from './client'
import type {
  Agent,
  AgentCreateRequest,
  AgentDetail,
  AgentHealthResult,
  AgentPreviewRequest,
  AgentPreviewResult,
  AgentRefreshResult,
  AgentUpdateRequest,
  PageResult,
} from '@/types'

export interface AgentListParams {
  health_status?: string
  enabled?: string
  q?: string
  limit?: number
  cursor?: string
}

export const agentsApi = {
  async list(params: AgentListParams = {}): Promise<PageResult<Agent>> {
    const { data } = await apiClient.get<PageResult<Agent>>('/agents', { params })
    return data
  },

  /** 两段式注册第一步：只拉取并校验 Card，不落库。 */
  async preview(body: AgentPreviewRequest): Promise<AgentPreviewResult> {
    const { data } = await apiClient.post<AgentPreviewResult>('/agents/preview', body)
    return data
  },

  async create(body: AgentCreateRequest): Promise<AgentDetail> {
    const { data } = await apiClient.post<AgentDetail>('/agents', body)
    return data
  },

  async get(id: string): Promise<AgentDetail> {
    const { data } = await apiClient.get<AgentDetail>(`/agents/${id}`)
    return data
  },

  async update(id: string, body: AgentUpdateRequest): Promise<AgentDetail> {
    const { data } = await apiClient.patch<AgentDetail>(`/agents/${id}`, body)
    return data
  },

  async remove(id: string): Promise<void> {
    await apiClient.delete(`/agents/${id}`)
  },

  async refresh(id: string): Promise<AgentRefreshResult> {
    const { data } = await apiClient.post<AgentRefreshResult>(`/agents/${id}/refresh`)
    return data
  },

  async health(id: string): Promise<AgentHealthResult> {
    const { data } = await apiClient.post<AgentHealthResult>(`/agents/${id}/health`)
    return data
  },
}
