{"content": """"Run a few delegated chat tests and print compact evidence."""

import json

import httpx


BASE = 'http://127.0.0.1:8000/api/v1'
TOKEN = open('.tmp/ah_token').read().strip()

TASKS = [
    (
        'translator',
        '请调用 send_message 工具，agent=translator，任务：把“今天的天气很好，我们一起去公园散步吧。”翻译成英文，并说明检测到的源语言。',
    ),
    (
        'code-assistant',
        '请调用 send_message 工具，agent=code-assistant，任务：检查这段 Python 代码的质量并给出改进建议：def f(x): return x*2+1',
    ),
    (
        'research',
        '请调用 send_message 工具，agent=research，任务：对下面这段文字做摘要、提取关键词并估算阅读时间——人工智能正在改变软件开发方式。开发者可以用大模型辅助写代码、审查代码和生成测试，但需要人工验证结果的正确性。',
    ),
]


def run(message):
    headers = {
        'Authorization': f'Bearer {TOKEN}',
        'Content-Type': 'application/json',
        'Accept': 'text/event-stream',
    }
    run_id = None
    text_parts = []
    a2a_states = []
    task_summaries = []
    tool_results = []
    event_counts = {}
    current_event = None
    data_lines = []
    with httpx.Client(timeout=httpx.Timeout(240, read=240), trust_env=False) as client:
        with client.stream('POST', f'{BASE}/chat/stream', headers=headers,
                           json={'message': message}) as resp:
            run_id = resp.headers.get('X-Run-ID')
            if resp.status_code != 200:
                return {'error': resp.read().decode()[:500]}
            for line in resp.iter_lines():
                if line == '':
                    if current_event:
                        raw = '\n'.join(data_lines)
                        try:
                            data = json.loads(raw) if raw else {}
                        except json.JSONDecodeError:
                            data = {}
                        event_counts[current_event] = event_counts.get(current_event, 0) + 1
                        if current_event == 'a2a.task':
                            a2a_states.append(data.get('state'))
                            if data.get('result_summary'):
                                task_summaries.append(data['result_summary'])
                        elif current_event == 'tool.result':
                            tool_results.append(data.get('summary', ''))
                        elif current_event == 'message.delta':
                            text_parts.append(data.get('delta', ''))
                        elif current_event == 'error':
                            tool_results.append('ERROR: ' + json.dumps(data, ensure_ascii=False))
                    current_event = None
                    data_lines = []
                    continue
                if line.startswith('event:'):
                    current_event = line[6:].strip()
                elif line.startswith('data:'):
                    data_lines.append(line[5:].lstrip())
    return {
        'run_id': run_id,
        'events': event_counts,
        'a2a_states': a2a_states,
        'tool_results': tool_results,
        'text': ''.join(text_parts),
    }


for slug, message in TASKS:
    print('=' * 80)
    print(f'TASK {slug}')
    result = run(message)
    print('run_id:', result.get('run_id'))
    print('events:', json.dumps(result.get('events'), ensure_ascii=False))
    print('a2a_states:', ' -> '.join(result.get('a2a_states') or []))
    tool = (result.get('tool_results') or [''])[0]
    print('tool.result:', tool[:500])
    print('assistant:', (result.get('text') or '')[:800])
