await page.waitForURL(/\/chat/);
// screenshot chat
await page.goto('http://127.0.0.1:5173/agents');
await page.waitForTimeout(2000);
await page.screenshot({path:'.tmp/agents-page.png', fullPage:true});
// back to chat, send message
...
```

