{"content": "import { chromium } from '@playwright/test'
import { mkdirSync } from 'node:fs'

const BASE = 'http://127.0.0.1:5173'
const OUT = '.tmp/screenshots'
mkdirSync(OUT, { recursive: true })

const browser = await chromium.launch({ args: ['--no-proxy-server'] })
const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } })
const consoleErrors = []
page.on('console', (msg) => {
  if (msg.type() === 'error') consoleErrors.push(msg.text())
})
page.on('pageerror', (err) => consoleErrors.push(String(err)))

try {
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' })
  await page.getByPlaceholder('you@example.com').fill('dev@example.com')
  await page.getByPlaceholder('至少 8 位').fill('dev-password-123')
  await page.getByRole('button', { name: '登录', exact: true }).click()
  await page.waitForURL(/\/chat(\?.*)?$/, { timeout: 20000 })
  await page.getByRole('textbox', { name: '输入消息' }).waitFor({ timeout: 15000 })
  console.log('[OK] login ->', page.url())

  await page.goto(`${BASE}/agents`, { waitUntil: 'networkidle' })
  await page.getByText('weather_agent').first().waitFor({ timeout: 20000 })
  const agentCards = await page.locator('text=_agent').count()
  console.log('[OK] agents page, _agent occurrences =', agentCards)
  await page.screenshot({ path: `${OUT}/agents-page.png`, fullPage: true })

  await page.goto(`${BASE}/tasks`, { waitUntil: 'networkidle' })
  await page.waitForTimeout(1500)
  await page.screenshot({ path: `${OUT}/tasks-page.png`, fullPage: true })
  console.log('[OK] tasks page captured')

  await page.goto(`${BASE}/chat`, { waitUntil: 'networkidle' })
  const composer = page.getByRole('textbox', { name: '输入消息' })
  await composer.waitFor({ timeout: 15000 })
  await composer.fill('请调用 send_message 工具，agent=math，任务：计算 6*7，并告诉我结果。')
  await page.getByRole('button', { name: '发送' }).click()
  console.log('[..] message sent, waiting for A2A reply')

  await page.getByText('math_agent').first().waitFor({ timeout: 120000 })
  await page.getByText(/42/).first().waitFor({ timeout: 120000 })
  await page.getByRole('button', { name: '发送' }).waitFor({ timeout: 120000 })
  await page.screenshot({ path: `${OUT}/chat-a2a.png`, fullPage: true })
  const bodyText = await page.locator('body').innerText()
  console.log('[OK] A2A reply visible; contains 42 =', bodyText.includes('42'))
  console.log('[OK] contains math_agent =', bodyText.includes('math_agent'))
  console.log('[OK] contains 远程 =', bodyText.includes('远程'))
  console.log('[screenshot]', `${OUT}/chat-a2a.png`)
} catch (error) {
  console.error('[FAIL]', error)
  try {
    await page.screenshot({ path: `${OUT}/failure.png`, fullPage: true })
  } catch {}
  process.exitCode = 1
} finally {
  console.log('[console errors]', JSON.stringify(consoleErrors.slice(0, 10)))
  await browser.close()
}
